import{_ as n,y as o,a as s,o as i,a2 as t,D as a}from"./chunks/framework.DCcmcJcL.js";const f=JSON.parse('{"title":"EU Withdrawal","description":"","frontmatter":{},"headers":[],"relativePath":"orders/eu-withdrawal.md","filePath":"orders/eu-withdrawal.md","lastUpdated":1789441803000}'),h={name:"orders/eu-withdrawal.md"};function d(l,e,g,c,u,w){const r=o("ImagePopup");return i(),s("div",null,[e[0]||(e[0]=t('<h1 id="eu-withdrawal" tabindex="-1">EU Withdrawal <a class="header-anchor" href="#eu-withdrawal" aria-label="Permalink to &quot;EU Withdrawal&quot;">​</a></h1><p>Consumers in the EU have the right to withdraw from an online purchase. EU Withdrawal gives them an online way to do it, as Directive (EU) 2023/2673 requires. Customers and guests send a withdrawal declaration from the storefront and receive a confirmation by email. You then record the outcome, refunded or declined, in the admin panel.</p><h2 id="before-you-start" tabindex="-1">Before you start <a class="header-anchor" href="#before-you-start" aria-label="Permalink to &quot;Before you start&quot;">​</a></h2><ul><li>Turn the feature on for each channel that sells to EU consumers, in <a href="./../configure/eu-withdrawals.html">EU Withdrawals</a>. It&#39;s off by default. While it&#39;s off, the storefront button and link are hidden and the withdrawal forms can&#39;t be opened.</li><li>The emails are sent from the sender name and address in <a href="./../configure/email-settings.html">Email Settings</a>.</li><li>The email with a guest&#39;s withdrawal link is sent as a background job. If guests don&#39;t receive it, ask whoever manages your server to check the queue. See <a href="./../getting-started/scheduled-tasks.html">Scheduled Tasks</a>.</li></ul><h2 id="which-orders-can-be-withdrawn" tabindex="-1">Which orders can be withdrawn <a class="header-anchor" href="#which-orders-can-be-withdrawn" aria-label="Permalink to &quot;Which orders can be withdrawn&quot;">​</a></h2><ul><li>A withdrawal covers the whole order. Customers can&#39;t choose products.</li><li>Each order can have one withdrawal. It can&#39;t be submitted again, even after you decline it.</li><li>Bagisto accepts a withdrawal for any order on a channel where the feature is on. It doesn&#39;t check how old the order is, its status or whether it was delivered. Check that the customer is within the withdrawal period before you refund, and decline the withdrawal if not.</li></ul><h2 id="customers-withdraw-from-an-order" tabindex="-1">Customers: withdraw from an order <a class="header-anchor" href="#customers-withdraw-from-an-order" aria-label="Permalink to &quot;Customers: withdraw from an order&quot;">​</a></h2><ol><li>Sign in to the storefront account and open <strong>Orders</strong>.</li><li>Open the order.</li><li>Click <strong>Withdraw from Contract</strong>. The <strong>Confirm Withdrawal from Contract</strong> page opens.</li><li>Check the order under <strong>Order</strong>: its number, date, <strong>Total</strong> and <strong>Items</strong> (the total quantity).</li><li>Enter a <strong>Reason</strong>, if the customer wants to give one. It&#39;s optional, up to 5,000 characters.</li><li>Click <strong>Submit withdrawal</strong>.</li></ol><p>The notice <strong>This is a legally binding declaration</strong> explains that the withdrawal takes effect as soon as it&#39;s submitted. <strong>Cancel and go back</strong> returns to the order without submitting.</p><p>Once a withdrawal exists, the button on the order reads <strong>View your withdrawal</strong> and opens the receipt.</p><h2 id="guests-withdraw-from-an-order" tabindex="-1">Guests: withdraw from an order <a class="header-anchor" href="#guests-withdraw-from-an-order" aria-label="Permalink to &quot;Guests: withdraw from an order&quot;">​</a></h2><ol><li>On the storefront, open the profile menu in the header.</li><li>Click <strong>Withdraw from a Contract</strong>. The <strong>Withdraw from Your Contract</strong> page opens.</li><li>Enter the <strong>Order number</strong> and the <strong>Email address</strong> used at checkout.</li><li>Click <strong>Send me the withdrawal link</strong>.</li><li>Open the email <strong>Your withdrawal link</strong> and click <strong>Open the withdrawal form</strong>.</li><li>Enter a <strong>Reason</strong>, if wanted, up to 5,000 characters.</li><li>Click <strong>Submit withdrawal</strong>.</li></ol><ul><li>The page shows the same notice whether or not an order matches, so it can&#39;t be used to find out order numbers.</li><li>Only guest orders placed on the same channel match. Customers with an account sign in and withdraw from their order page.</li><li>The link works for 24 hours. Once it expires, it opens a <strong>403 Forbidden</strong> page; request a new link. The link to the receipt also works for 24 hours. If the withdrawal was already submitted, a new link opens its receipt.</li><li>On the guest form, <strong>Cancel and go back</strong> returns to the home page.</li><li>The <strong>Withdraw from a Contract</strong> link is in the desktop header for visitors who aren&#39;t signed in. On phones the header has no link; guests can open <strong>/withdraw</strong> on your store&#39;s address, so consider linking to it from a CMS page.</li><li>The page can be used only a few times a minute from the same connection, to prevent abuse. If a guest tries too often, an error page shows; they can wait a minute and try again.</li></ul><h2 id="the-receipt" tabindex="-1">The receipt <a class="header-anchor" href="#the-receipt" aria-label="Permalink to &quot;The receipt&quot;">​</a></h2><p>After submitting, the customer sees the receipt. Its heading follows the status: <strong>Your withdrawal has been received</strong>, <strong>Your refund has been issued</strong> or <strong>Your withdrawal was declined</strong>.</p>',15)),a(r,{src:"/images/orders/eu-receipt.png",alt:"Withdrawal receipt with the reference, order and next steps"}),e[1]||(e[1]=t('<p>The receipt shows:</p><ul><li><strong>Received at</strong>, in UTC;</li><li><strong>Reference</strong>, with a button to copy it;</li><li><strong>Order</strong>, which links to the order for signed-in customers;</li><li><strong>Email</strong>, <strong>Status</strong> and <strong>Reason</strong>;</li><li><strong>What happens next</strong>, which lists the declaration, the confirmation email and the refund or decline, with your reason when you decline.</li></ul><p><strong>Print</strong> prints the receipt. The customer can save or print it as their record.</p><h2 id="the-confirmation-email" tabindex="-1">The confirmation email <a class="header-anchor" href="#the-confirmation-email" aria-label="Permalink to &quot;The confirmation email&quot;">​</a></h2><p>When a withdrawal is submitted, the customer is emailed straight away, in the language they used on the storefront. The subject is <strong>Confirmation of your withdrawal — Order</strong> and the order number. The email lists the reference, the time it was received in UTC, the order and the email, and the reason when one was given. This email is the confirmation on a durable medium that the directive requires.</p><p>You aren&#39;t emailed about new withdrawals. Check <strong>Sales &gt;&gt; EU Withdrawals</strong> regularly.</p><h2 id="manage-withdrawals" tabindex="-1">Manage withdrawals <a class="header-anchor" href="#manage-withdrawals" aria-label="Permalink to &quot;Manage withdrawals&quot;">​</a></h2><h3 id="the-eu-withdrawals-screen" tabindex="-1">The EU Withdrawals screen <a class="header-anchor" href="#the-eu-withdrawals-screen" aria-label="Permalink to &quot;The EU Withdrawals screen&quot;">​</a></h3><p>Go to <strong>Sales &gt;&gt; EU Withdrawals</strong>. The newest withdrawals are listed first.</p>',9)),a(r,{src:"/images/orders/eu-grid.png",alt:"EU Withdrawals screen listing withdrawals with their status"}),e[2]||(e[2]=t('<table tabindex="0"><thead><tr><th>Column</th><th>What it shows</th></tr></thead><tbody><tr><td><strong>Received At</strong></td><td>When the customer submitted the withdrawal.</td></tr><tr><td><strong>Order</strong></td><td>The order number, which opens the order.</td></tr><tr><td><strong>Customer Email</strong></td><td>The email used at checkout.</td></tr><tr><td><strong>Status</strong></td><td><strong>Received</strong> in yellow, <strong>Refunded</strong> in green or <strong>Declined</strong> in red.</td></tr><tr><td><strong>Channel</strong></td><td>The code of the channel the order was placed on.</td></tr><tr><td><strong>Confirmation Sent</strong></td><td>When the first confirmation email was sent. Empty if it hasn&#39;t been sent.</td></tr><tr><td><strong>Reference</strong></td><td>The withdrawal&#39;s reference, the one the customer sees.</td></tr></tbody></table><ul><li><strong>Search</strong>: find withdrawals by order, customer email or reference.</li><li><strong>Filter</strong>: narrow the list by any column, with date ranges for <strong>Received At</strong> and <strong>Confirmation Sent</strong>.</li><li><strong>Export</strong>: downloads the withdrawals as a <strong>CSV</strong>, <strong>XLS</strong> or <strong>XLSX</strong> file.</li><li><strong>View</strong>: opens the withdrawal.</li></ul><h3 id="the-withdrawal-page" tabindex="-1">The withdrawal page <a class="header-anchor" href="#the-withdrawal-page" aria-label="Permalink to &quot;The withdrawal page&quot;">​</a></h3><p>The title shows <strong>Withdrawal</strong> and its ID, with the status and <strong>Guest</strong> for a guest order. <strong>Back to list</strong> returns to the screen.</p>',4)),a(r,{src:"/images/orders/eu-view.png",alt:"Withdrawal page with the evidence, timeline and actions"}),e[3]||(e[3]=t('<ul><li><strong>Evidence</strong> holds what was recorded when the customer submitted, and can&#39;t be changed: <strong>Received At</strong>, <strong>Reference</strong>, <strong>Order</strong>, <strong>Customer Email</strong>, <strong>Channel</strong>, <strong>Locale</strong> and, if the customer gave one, <strong>Customer’s reason</strong>. <strong>Reference</strong> has a button to copy it. Times on the <strong>EU Withdrawals</strong> screen and this page use your store&#39;s time zone (<strong>Timezone</strong> in <a href="./../configure/about.html">About</a>); the storefront and emails use UTC.</li><li><strong>Timeline</strong> shows <strong>Declaration Received</strong>, then <strong>Initial Confirmation Email</strong> (sent, failed with the error, or not sent yet), then the outcome (<strong>Withdrawal Declined</strong> with your reason, <strong>Refund Issued</strong> with your note, or <strong>Resolution Pending</strong>), and, once there&#39;s an outcome, <strong>Final Confirmation Email</strong>.</li><li><strong>Actions</strong> holds the buttons below. Each one needs its permission.</li></ul><p>Recording an outcome doesn&#39;t refund the customer or change the order. Refund the order with <a href="./create-refunds.html">Create Refund</a> or through a return request in <a href="./rma.html">RMA</a>, then record it here.</p>',2)),a(r,{src:"/images/orders/eu-actions.png",alt:"Actions card with the refund reference, decline reason and email buttons"}),e[4]||(e[4]=t('<h3 id="record-a-refund" tabindex="-1">Record a refund <a class="header-anchor" href="#record-a-refund" aria-label="Permalink to &quot;Record a refund&quot;">​</a></h3><ol><li>Refund the order.</li><li>Go to <strong>Sales &gt;&gt; EU Withdrawals</strong>.</li><li>Open the withdrawal.</li><li>In <strong>Refund reference (optional)</strong>, enter a note such as the refund number. Up to 500 characters.</li><li>Click <strong>Mark as Refunded</strong>.</li><li>Click <strong>Agree</strong>.</li></ol><p>The status becomes <strong>Refunded</strong>, and the time, your name and the reference are recorded. The customer&#39;s receipt shows the new status straight away. No email is sent. To tell the customer, <a href="#tell-the-customer-the-outcome">send the final confirmation email</a>. If you click <strong>Mark as Refunded</strong> again, the time, your name and the reference are replaced, so enter the reference again.</p><h3 id="decline-a-withdrawal" tabindex="-1">Decline a withdrawal <a class="header-anchor" href="#decline-a-withdrawal" aria-label="Permalink to &quot;Decline a withdrawal&quot;">​</a></h3><p>Decline a withdrawal when you contest the customer&#39;s right to withdraw.</p><ol><li>Go to <strong>Sales &gt;&gt; EU Withdrawals</strong>.</li><li>Open the withdrawal.</li><li>In <strong>Reason for declining</strong>, explain why. It&#39;s required, up to 500 characters, and the customer can see it.</li><li>Click <strong>Decline Withdrawal</strong>.</li><li>Click <strong>Agree</strong>.</li></ol><p>The status becomes <strong>Declined</strong>, and the time, reason and your name are recorded. The customer&#39;s receipt shows the new status straight away. No email is sent.</p><h3 id="tell-the-customer-the-outcome" tabindex="-1">Tell the customer the outcome <a class="header-anchor" href="#tell-the-customer-the-outcome" aria-label="Permalink to &quot;Tell the customer the outcome&quot;">​</a></h3><ol><li>Go to <strong>Sales &gt;&gt; EU Withdrawals</strong>.</li><li>Open the withdrawal.</li><li>Click <strong>Send Final Confirmation Email</strong>.</li><li>Click <strong>Agree</strong>.</li></ol><p>The customer receives the confirmation email again, titled <strong>Refund issued</strong> or <strong>Withdrawal declined</strong>. While a withdrawal is still <strong>Received</strong>, the button reads <strong>Resend Confirmation Email</strong> and sends the first confirmation again, for example when it failed or didn&#39;t arrive. If sending fails, you see <strong>Could not send the confirmation email. See the timeline for details.</strong> Check <a href="./../configure/email-settings.html">Email Settings</a> and try again.</p><div class="warning custom-block"><p class="custom-block-title">Record the outcome once</p><p>Both <strong>Mark as Refunded</strong> and <strong>Decline Withdrawal</strong> stay available after you record an outcome, and recording the other one replaces the first. If you change the outcome, send the final confirmation email again so the customer gets the new outcome.</p></div><h2 id="statuses" tabindex="-1">Statuses <a class="header-anchor" href="#statuses" aria-label="Permalink to &quot;Statuses&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Status</th><th>What it means</th></tr></thead><tbody><tr><td><strong>Received</strong></td><td>The customer submitted the withdrawal, and it&#39;s waiting for your decision.</td></tr><tr><td><strong>Refunded</strong></td><td>You recorded that the order was refunded.</td></tr><tr><td><strong>Declined</strong></td><td>You contested the withdrawal and gave a reason.</td></tr></tbody></table><p>The withdrawal&#39;s status doesn&#39;t change the order&#39;s status.</p><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h2><p>A role needs <strong>EU Withdrawals</strong> under <strong>Sales</strong> to see the screen, with:</p><ul><li><strong>View</strong> to open a withdrawal;</li><li><strong>Decline</strong> for <strong>Decline Withdrawal</strong>;</li><li><strong>Mark Refunded</strong> for <strong>Mark as Refunded</strong>;</li><li><strong>Resend Confirmation</strong> for <strong>Resend Confirmation Email</strong> and <strong>Send Final Confirmation Email</strong>.</li></ul>',17))])}const p=n(h,[["render",d]]);export{f as __pageData,p as default};
